 if(!leagues.size)return[];
 const ids=[...leagues.keys()].join(',');
 const raw=await smPages('fixtures/date/'+date,token,fetcher,{params:{include:'participants;league.country;state;scores',filters:'fixtureLeagues:'+ids}});
